-- Nomeriq Growth — complete schema.
-- Target: PostgreSQL 15+ (Supabase) and PGlite (local development).
-- All timestamps are timestamptz. UUIDs are generated by the application.

CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  normalized_email text NOT NULL UNIQUE,
  name text NOT NULL,
  password_hash text NOT NULL,
  role text NOT NULL DEFAULT 'member'
    CHECK (role IN ('founder', 'admin', 'member')),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz
);

CREATE TABLE IF NOT EXISTS sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  user_agent text
);

CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS workspace_settings (
  id text PRIMARY KEY DEFAULT 'default',
  legal_business_name text NOT NULL DEFAULT 'Nomeriq',
  postal_address text NOT NULL DEFAULT '',
  sender_signature text NOT NULL DEFAULT 'Founder
Nomeriq',
  footer_note text NOT NULL DEFAULT 'You are receiving this because we believe your business may be a fit for Nomeriq.',
  follow_up_max integer NOT NULL DEFAULT 2 CHECK (follow_up_max BETWEEN 0 AND 3),
  follow_up_delay_1_days integer NOT NULL DEFAULT 4 CHECK (follow_up_delay_1_days BETWEEN 1 AND 60),
  follow_up_delay_2_days integer NOT NULL DEFAULT 7 CHECK (follow_up_delay_2_days BETWEEN 1 AND 60),
  sync_stale_hours integer NOT NULL DEFAULT 24 CHECK (sync_stale_hours BETWEEN 1 AND 720),
  timezone text NOT NULL DEFAULT 'Asia/Karachi',
  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS product_truth (
  id uuid PRIMARY KEY,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'needs_review'
    CHECK (status IN ('needs_review', 'approved')),
  one_liner text NOT NULL DEFAULT '',
  offer_summary text NOT NULL DEFAULT '',
  how_it_works text NOT NULL DEFAULT '',
  pricing_notes text NOT NULL DEFAULT '',
  integrations text NOT NULL DEFAULT '',
  limitations text NOT NULL DEFAULT '',
  approved_claims jsonb NOT NULL DEFAULT '[]'::jsonb,
  prohibited_claims jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
  approved_by uuid REFERENCES users(id) ON DELETE SET NULL,
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS product_truth_revisions (
  id uuid PRIMARY KEY,
  product_truth_id uuid NOT NULL REFERENCES product_truth(id) ON DELETE CASCADE,
  version integer NOT NULL,
  snapshot jsonb NOT NULL,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS research_jobs (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  target_count integer NOT NULL CHECK (target_count BETWEEN 1 AND 10000),
  categories jsonb NOT NULL DEFAULT '[]'::jsonb,
  regions text NOT NULL DEFAULT 'Worldwide',
  requirements text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'paused', 'completed', 'archived')),
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  notes text NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS prospects (
  id uuid PRIMARY KEY,
  business_name text NOT NULL,
  name_key text NOT NULL,
  website_url text,
  domain_key text,
  country text,
  categories jsonb NOT NULL DEFAULT '[]'::jsonb,
  signal_description text,
  pricing_details text,
  qualification_status text NOT NULL DEFAULT 'candidate'
    CHECK (qualification_status IN ('candidate', 'verified', 'rejected')),
  rejection_reason text,
  evidence_summary text,
  research_notes text,
  instagram_key text,
  instagram_url text,
  youtube_key text,
  youtube_url text,
  x_key text,
  x_url text,
  telegram_key text,
  telegram_url text,
  linkedin_url text,
  other_socials jsonb NOT NULL DEFAULT '[]'::jsonb,
  follower_count text,
  subscriber_count text,
  verified_at timestamptz,
  status text NOT NULL DEFAULT 'new'
    CHECK (status IN ('new', 'verified', 'draft_prepared', 'contacted', 'replied',
      'interested', 'demo', 'proposal', 'won', 'lost')),
  next_action text,
  next_action_at timestamptz,
  founder_notes text,
  do_not_contact boolean NOT NULL DEFAULT false,
  research_job_id uuid REFERENCES research_jobs(id) ON DELETE SET NULL,
  created_by_type text NOT NULL DEFAULT 'founder'
    CHECK (created_by_type IN ('founder', 'chatgpt', 'claude', 'api', 'seed')),
  created_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  created_by_key_id uuid,
  last_contacted_at timestamptz,
  last_reply_at timestamptz,
  archived_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  founder_edited_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS prospects_domain_unique
  ON prospects (domain_key) WHERE domain_key IS NOT NULL AND archived_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS prospects_instagram_unique
  ON prospects (instagram_key) WHERE instagram_key IS NOT NULL AND archived_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS prospects_youtube_unique
  ON prospects (youtube_key) WHERE youtube_key IS NOT NULL AND archived_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS prospects_x_unique
  ON prospects (x_key) WHERE x_key IS NOT NULL AND archived_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS prospects_telegram_unique
  ON prospects (telegram_key) WHERE telegram_key IS NOT NULL AND archived_at IS NULL;
CREATE INDEX IF NOT EXISTS prospects_status_idx ON prospects(status);
CREATE INDEX IF NOT EXISTS prospects_qualification_idx ON prospects(qualification_status);
CREATE INDEX IF NOT EXISTS prospects_job_idx ON prospects(research_job_id);
CREATE INDEX IF NOT EXISTS prospects_updated_idx ON prospects(updated_at DESC);

CREATE TABLE IF NOT EXISTS prospect_aliases (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  alias text NOT NULL,
  alias_key text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS prospect_aliases_prospect_idx ON prospect_aliases(prospect_id);

CREATE TABLE IF NOT EXISTS prospect_emails (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  email text NOT NULL,
  normalized_email text NOT NULL UNIQUE,
  source_url text NOT NULL,
  source_type text NOT NULL DEFAULT 'official_website'
    CHECK (source_type IN ('official_website', 'official_social', 'official_directory', 'public_profile')),
  is_primary boolean NOT NULL DEFAULT true,
  verified_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS prospect_emails_prospect_idx ON prospect_emails(prospect_id);

CREATE TABLE IF NOT EXISTS prospect_sources (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  url text NOT NULL,
  label text NOT NULL,
  source_type text NOT NULL DEFAULT 'website',
  observed_at timestamptz NOT NULL DEFAULT now(),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS prospect_sources_prospect_idx ON prospect_sources(prospect_id);

CREATE TABLE IF NOT EXISTS research_events (
  id uuid PRIMARY KEY,
  job_id uuid NOT NULL REFERENCES research_jobs(id) ON DELETE CASCADE,
  event_type text NOT NULL
    CHECK (event_type IN ('candidate_saved', 'verified_saved', 'draft_saved',
      'duplicate_rejected', 'lead_rejected', 'note')),
  prospect_id uuid REFERENCES prospects(id) ON DELETE SET NULL,
  detail jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by_type text NOT NULL DEFAULT 'founder',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS research_events_job_idx ON research_events(job_id, created_at DESC);

CREATE TABLE IF NOT EXISTS drafts (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  research_job_id uuid REFERENCES research_jobs(id) ON DELETE SET NULL,
  kind text NOT NULL DEFAULT 'first_contact'
    CHECK (kind IN ('first_contact', 'follow_up')),
  sequence integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'approved', 'sent', 'discarded', 'cancelled')),
  subject text NOT NULL,
  body text NOT NULL,
  recipient_email text NOT NULL,
  ai_generated boolean NOT NULL DEFAULT false,
  ai_model text,
  product_truth_version integer,
  warnings jsonb NOT NULL DEFAULT '[]'::jsonb,
  founder_edited boolean NOT NULL DEFAULT false,
  approved_at timestamptz,
  approved_by uuid REFERENCES users(id) ON DELETE SET NULL,
  sent_at timestamptz,
  created_by_type text NOT NULL DEFAULT 'founder'
    CHECK (created_by_type IN ('founder', 'chatgpt', 'claude', 'api', 'seed')),
  created_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS drafts_one_first_contact
  ON drafts (prospect_id) WHERE kind = 'first_contact';
CREATE UNIQUE INDEX IF NOT EXISTS drafts_one_follow_up_sequence
  ON drafts (prospect_id, sequence) WHERE kind = 'follow_up';
CREATE INDEX IF NOT EXISTS drafts_status_idx ON drafts(status);
CREATE INDEX IF NOT EXISTS drafts_prospect_idx ON drafts(prospect_id);

CREATE TABLE IF NOT EXISTS draft_revisions (
  id uuid PRIMARY KEY,
  draft_id uuid NOT NULL REFERENCES drafts(id) ON DELETE CASCADE,
  subject text NOT NULL,
  body text NOT NULL,
  recipient_email text NOT NULL,
  warnings jsonb NOT NULL DEFAULT '[]'::jsonb,
  edited_by uuid REFERENCES users(id) ON DELETE SET NULL,
  edited_by_type text NOT NULL DEFAULT 'founder',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS draft_revisions_draft_idx ON draft_revisions(draft_id, created_at DESC);

CREATE TABLE IF NOT EXISTS email_accounts (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  provider text NOT NULL DEFAULT 'ionos'
    CHECK (provider IN ('ionos', 'smtp_imap', 'sandbox')),
  email_address text NOT NULL,
  normalized_email text NOT NULL UNIQUE,
  from_name text NOT NULL,
  reply_to text,
  smtp_host text NOT NULL DEFAULT '',
  smtp_port integer NOT NULL DEFAULT 587,
  smtp_secure boolean NOT NULL DEFAULT false,
  imap_host text NOT NULL DEFAULT '',
  imap_port integer NOT NULL DEFAULT 993,
  imap_secure boolean NOT NULL DEFAULT true,
  username text NOT NULL DEFAULT '',
  password_encrypted text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'unverified'
    CHECK (status IN ('unverified', 'connected', 'error', 'disabled')),
  last_error text,
  last_checked_at timestamptz,
  last_sync_at timestamptz,
  daily_send_limit integer NOT NULL DEFAULT 25 CHECK (daily_send_limit BETWEEN 1 AND 500),
  min_interval_seconds integer NOT NULL DEFAULT 60 CHECK (min_interval_seconds BETWEEN 5 AND 3600),
  is_default boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS email_accounts_status_idx ON email_accounts(status);

CREATE TABLE IF NOT EXISTS mailbox_sync_state (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES email_accounts(id) ON DELETE CASCADE,
  folder text NOT NULL,
  uidvalidity bigint,
  last_uid bigint NOT NULL DEFAULT 0,
  last_synced_at timestamptz,
  history_complete boolean NOT NULL DEFAULT false,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, folder)
);

CREATE TABLE IF NOT EXISTS conversations (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL UNIQUE REFERENCES prospects(id) ON DELETE CASCADE,
  subject text NOT NULL,
  status text NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'waiting', 'replied', 'closed')),
  classification text NOT NULL DEFAULT 'other'
    CHECK (classification IN ('interested', 'demo', 'features', 'pricing', 'technical',
      'not_interested', 'unsubscribe', 'other')),
  classification_source text NOT NULL DEFAULT 'rules'
    CHECK (classification_source IN ('rules', 'ai', 'founder')),
  classification_confidence numeric(3,2),
  last_message_at timestamptz,
  last_inbound_at timestamptz,
  last_outbound_at timestamptz,
  unread_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS conversations_updated_idx ON conversations(updated_at DESC);

CREATE TABLE IF NOT EXISTS messages (
  id uuid PRIMARY KEY,
  conversation_id uuid REFERENCES conversations(id) ON DELETE SET NULL,
  prospect_id uuid REFERENCES prospects(id) ON DELETE SET NULL,
  account_id uuid REFERENCES email_accounts(id) ON DELETE SET NULL,
  direction text NOT NULL CHECK (direction IN ('outbound', 'inbound')),
  source text NOT NULL DEFAULT 'smtp'
    CHECK (source IN ('smtp', 'imap', 'seed', 'system')),
  folder text,
  uidvalidity bigint,
  uid bigint,
  message_id text,
  in_reply_to text,
  references_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  from_email text NOT NULL,
  from_name text,
  to_emails jsonb NOT NULL DEFAULT '[]'::jsonb,
  cc_emails jsonb NOT NULL DEFAULT '[]'::jsonb,
  subject text NOT NULL DEFAULT '',
  body_text text NOT NULL DEFAULT '',
  body_html text,
  snippet text,
  sent_at timestamptz,
  received_at timestamptz,
  is_read boolean NOT NULL DEFAULT false,
  is_sandbox boolean NOT NULL DEFAULT false,
  delivery_status text NOT NULL DEFAULT 'accepted'
    CHECK (delivery_status IN ('sandbox', 'accepted', 'failed', 'bounced', 'uncertain')),
  error text,
  attachments jsonb NOT NULL DEFAULT '[]'::jsonb,
  draft_id uuid REFERENCES drafts(id) ON DELETE SET NULL,
  campaign_id uuid,
  external boolean NOT NULL DEFAULT false,
  matched_by text,
  raw_headers jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS message_attachments (
  id uuid PRIMARY KEY,
  message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  filename text NOT NULL,
  content_type text NOT NULL DEFAULT 'application/octet-stream',
  size integer NOT NULL,
  content bytea,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS message_attachments_message_idx ON message_attachments(message_id);

CREATE UNIQUE INDEX IF NOT EXISTS messages_account_message_unique
  ON messages (account_id, message_id) WHERE message_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS messages_imap_unique
  ON messages (account_id, folder, uidvalidity, uid)
  WHERE account_id IS NOT NULL AND uid IS NOT NULL AND uidvalidity IS NOT NULL;
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, created_at);
CREATE INDEX IF NOT EXISTS messages_prospect_idx ON messages(prospect_id, created_at DESC);
CREATE INDEX IF NOT EXISTS messages_inbox_idx ON messages(direction, created_at DESC);

CREATE TABLE IF NOT EXISTS outbound_sends (
  id uuid PRIMARY KEY,
  draft_id uuid UNIQUE REFERENCES drafts(id) ON DELETE CASCADE,
  conversation_id uuid REFERENCES conversations(id) ON DELETE SET NULL,
  kind text NOT NULL DEFAULT 'draft' CHECK (kind IN ('draft', 'reply')),
  recipient_email text,
  subject text,
  account_id uuid REFERENCES email_accounts(id) ON DELETE SET NULL,
  prospect_id uuid REFERENCES prospects(id) ON DELETE CASCADE,
  campaign_id uuid,
  idempotency_key text NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'sending'
    CHECK (status IN ('sending', 'accepted', 'sandbox', 'failed', 'uncertain', 'blocked')),
  transport_message_id text,
  smtp_response text,
  error text,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);

CREATE INDEX IF NOT EXISTS outbound_sends_prospect_idx ON outbound_sends(prospect_id, started_at DESC);

CREATE TABLE IF NOT EXISTS campaigns (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'approved', 'active', 'paused', 'completed', 'cancelled')),
  account_id uuid NOT NULL REFERENCES email_accounts(id) ON DELETE RESTRICT,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  approved_by uuid REFERENCES users(id) ON DELETE SET NULL,
  approved_at timestamptz,
  daily_send_limit_snapshot integer NOT NULL,
  min_interval_snapshot integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);

CREATE TABLE IF NOT EXISTS campaign_items (
  id uuid PRIMARY KEY,
  campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  draft_id uuid NOT NULL UNIQUE REFERENCES drafts(id) ON DELETE CASCADE,
  position integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'sending', 'sent', 'failed', 'skipped')),
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS campaign_items_campaign_idx ON campaign_items(campaign_id, position);

CREATE TABLE IF NOT EXISTS suppressions (
  id uuid PRIMARY KEY,
  normalized_email text NOT NULL UNIQUE,
  email text NOT NULL,
  reason text NOT NULL
    CHECK (reason IN ('unsubscribe', 'opt_out', 'bounce', 'complaint', 'manual')),
  source text NOT NULL DEFAULT 'founder',
  prospect_id uuid REFERENCES prospects(id) ON DELETE SET NULL,
  note text,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS unsubscribe_tokens (
  id uuid PRIMARY KEY,
  prospect_id uuid NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  normalized_email text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  used_at timestamptz
);

CREATE INDEX IF NOT EXISTS unsubscribe_tokens_prospect_idx ON unsubscribe_tokens(prospect_id);

CREATE TABLE IF NOT EXISTS api_keys (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  assistant text NOT NULL DEFAULT 'custom'
    CHECK (assistant IN ('chatgpt', 'claude', 'custom')),
  key_prefix text NOT NULL,
  key_hash text NOT NULL UNIQUE,
  scopes jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

CREATE TABLE IF NOT EXISTS audit_log (
  id uuid PRIMARY KEY,
  actor_type text NOT NULL,
  actor_id text,
  action text NOT NULL,
  entity_type text,
  entity_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS audit_log_created_idx ON audit_log(created_at DESC);
